-- ----------------- TABLE: users -----------------
CREATE TABLE IF NOT EXISTS public.users (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reg_no TEXT UNIQUE,
    name TEXT NOT NULL,
    phone TEXT NOT NULL,
    role TEXT NOT NULL,
    password TEXT,
    email TEXT,
    branch TEXT,
    section TEXT,
    year_of_study INTEGER,
    signature TEXT,
    profile_image TEXT,
    designation TEXT
);

ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public full access on users" ON public.users;
CREATE POLICY "Allow public full access on users" ON public.users FOR ALL TO anon, authenticated USING (true) WITH CHECK (true);

